// The technical export profile: the receipts as W3C PROV (PROV-JSON, https://www.w3.org/Submission/prov-json/),
// the raw observations, the versions that produced them and the steps to reproduce the check.
// Each receipt is a prov:Entity generated by one capture activity, associated with the adapter
// that read it; a finding's cites become wasDerivedFrom; the chain is an entity whose members are
// the receipts, so a PROV tool can walk from any fact to the root it sits under.

const NS = "dc";
const ent = (hash) => `${NS}:receipt-${hash}`;
const act = (hash) => `${NS}:capture-${hash}`;
const agentId = (adapter) => `${NS}:adapter-${String(adapter || "unknown").replace(/[^A-Za-z0-9.-]/g, "-")}`;

// PROV-JSON has no null: an absent attribute is left out (W3C PROV-JSON schema; prov 3.3 rejects null).
const compact = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== null && v !== undefined));

function receiptNodes(row, doc) {
  const r = row.receipt, cap = r.capture || {};
  doc.entity[ent(r.hash)] = compact({ "prov:type": "dc:Receipt", "dc:kind": r.kind, "dc:subject": r.subject, "dc:subjectKind": r.subjectKind,
    "dc:source": r.source, "dc:url": r.url, "dc:rawHash": cap.rawHash, "dc:seq": row.seq, "dc:link": row.link,
    "dc:catalogue": r.catalogue || null, "dc:doesNotProve": r.dnp, "prov:generatedAtTime": r.at });
  doc.activity[act(r.hash)] = compact({ "prov:startTime": r.at, "prov:endTime": r.at, "dc:method": cap.method || null });
  const ag = agentId(cap.adapter);
  doc.agent[ag] = compact({ "prov:type": "prov:SoftwareAgent", "dc:adapter": cap.adapter || null });
  doc.wasGeneratedBy[`${NS}:gen-${r.hash}`] = { "prov:entity": ent(r.hash), "prov:activity": act(r.hash), "prov:time": r.at };
  doc.wasAssociatedWith[`${NS}:assoc-${r.hash}`] = { "prov:activity": act(r.hash), "prov:agent": ag };
  for (const c of [].concat(r.cites || [])) doc.wasDerivedFrom[`${NS}:der-${r.hash}-${c}`] = { "prov:generatedEntity": ent(r.hash), "prov:usedEntity": ent(c) };
  if (r.witness) doc.entity[ent(r.hash)]["dc:witness"] = r.witness;
}

export function provDocument(ctx) {
  const { chain, rows } = ctx;
  const doc = { prefix: { dc: "https://github.com/HarperZ9/daylight-commons/blob/main/project-docs/EVIDENCE-LAYER.md#", prov: "http://www.w3.org/ns/prov#" },
    entity: {}, activity: {}, agent: {}, wasGeneratedBy: {}, wasAssociatedWith: {}, wasDerivedFrom: {}, hadMember: {} };
  for (const row of rows) receiptNodes(row, doc);
  const chainId = `${NS}:chain-${chain.root}`;
  doc.entity[chainId] = { "prov:type": "dc:EvidenceChain", "dc:format": chain.format, "dc:root": chain.root, "dc:head": chain.head, "dc:size": chain.size, "prov:generatedAtTime": chain.at };
  for (const row of rows) doc.hadMember[`${NS}:mem-${row.receipt.hash}`] = { "prov:collection": chainId, "prov:entity": ent(row.receipt.hash) };
  return doc;
}

function reproduce(ctx) {
  const versions = [...new Set(ctx.rows.map((r) => (r.receipt.capture || {}).adapter).filter(Boolean))];
  return [
    "# Reproduce this export",
    "",
    `Exported ${ctx.at} by ${ctx.tool} from an evidence chain of ${ctx.rows.length} receipts.`,
    "",
    `- Chain root: \`${ctx.chain.root}\``,
    `- Chain head: \`${ctx.chain.head}\``,
    `- Adapter versions: ${versions.map((v) => `\`${v}\``).join(", ") || "none recorded"}`,
    `- Receipt format: \`radar-receipt/1\`; chain format: \`${ctx.chain.format}\``,
    "",
    "## Check the chain",
    "",
    "```",
    "node bin/radar.mjs verify evidence-chain.json",
    "node bin/radar.mjs export evidence-chain.json --profile technical --out again",
    "```",
    "",
    "The second command rebuilds `observations.jsonl` and `provenance.json` from the chain alone; they match these files except for the export time.",
    "",
    `Read it as: ${ctx.dnp}`,
    "",
  ].join("\n");
}

export async function technicalFiles(ctx) {
  const obs = ctx.rows.map((row) => JSON.stringify({ seq: row.seq, link: row.link, proof: row.proof, receipt: row.receipt })).join("\n") + "\n";
  return {
    "provenance.json": JSON.stringify(provDocument(ctx), null, 2) + "\n",
    "observations.jsonl": obs,
    "REPRODUCE.md": reproduce(ctx),
  };
}
